import { useState, useEffect } from "react";

export default function MenuCard({
  item,
  quantity = 0,
  addToCart,
  isTopRated = false,
  isPopular = false,
  rating = 0,
  sold = 0
}) {
  const outOfStock = item.stock <= 0;

  // UI-only quantity (does NOT claim to update cart)
  const [localQty, setLocalQty] = useState(quantity);

  useEffect(() => {
    setLocalQty(quantity);
  }, [quantity]);

  const handleAdd = () => {
    addToCart(item);          // real cart update
    setLocalQty(q => q + 1);  // UI update
  };

  const handleRemove = () => {
    // ⚠️ Cart has no remove logic → UI only
    setLocalQty(q => Math.max(q - 1, 0));
  };

  return (
    <div className={`menu-card ${outOfStock ? "out" : ""}`}>
      {(isTopRated || isPopular) && (
        <div className="badges">
          {isTopRated && <span className="badge top">⭐ Top Rated</span>}
          {isPopular && <span className="badge hot">🔥 Popular</span>}
        </div>
      )}

      <h3>{item.name}</h3>
      <p className="price">₹{item.price}</p>

      <div className="rating">
        ⭐ {rating} | Sold: {sold}
      </div>

      <div className="stock">Stock: {item.stock}</div>

      {outOfStock ? (
        <button className="btn-disabled" disabled>
          Unavailable
        </button>
      ) : localQty === 0 ? (
        <button className="btn-add" onClick={handleAdd}>
          ADD
        </button>
      ) : (
        <div className="qty-box">
          <button onClick={handleRemove}>−</button>
          <span>{localQty}</span>
          <button onClick={handleAdd}>+</button>
        </div>
      )}
    </div>
  );
}
